  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  border-collapse: collapse;
  text-align: left;
  table-layout: fixed;
}

.sales-report__caption {
  padding: 0 0 6px;
  font-size: 13px;
  font-weight: 600;
