  align-items: center;
  gap: 4px;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.sales-report__sort:hover {
  text-decoration: underline;
}

.sales-report__sort:focus-visible,
