}

.sales-report__cell--revenue {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.sales-report__row-toggle {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.sales-report__chevron {
  width: 10px;
  font-size: 10px;
}

.sales-report__detail-cell {
  padding: 6px 8px 8px;
  border-bottom: 1px solid var(--border);
  background: var(--muted);
}

.sales-report__detail-label {
  margin-right: 8px;
  opacity: 0.75;
}

.sales-report__detail-value {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.sales-report__hint {
  margin: 0;
  font-size: 12px;
  opacity: 0.7;
}
